using Newtonsoft.Json;
using Newtonsoft.Json.Converters;

namespace CalradicExchange.Core.Model
{
    /// <summary>
    /// A world event translated by the game layer (EventBridge) or generated by Core itself (season change, famine).
    /// Field meaning per type:
    /// VillageLooted: SettlementId = village, ItemId = its primary product, TownId = bound town, KingdomId = owner kingdom.
    /// SiegeStarted/SiegeEnded/FamineStarted: TownId, KingdomId = defender/owner.
    /// SettlementCaptured: TownId, KingdomId = loser, OtherKingdomId = winner.
    /// WarDeclared/PeaceMade: KingdomId and OtherKingdomId.
    /// SeasonChanged: Season = the new season.
    /// </summary>
    public sealed class MarketEvent
    {
        [JsonConverter(typeof(StringEnumConverter))]
        public MarketEventType Type { get; set; }

        public int Day { get; set; }
        public string SettlementId { get; set; }
        public string ItemId { get; set; }
        public string TownId { get; set; }
        public string KingdomId { get; set; }
        public string OtherKingdomId { get; set; }

        [JsonConverter(typeof(StringEnumConverter))]
        public Season? Season { get; set; }

        public override string ToString()
        {
            return $"{Type} day={Day} settlement={SettlementId} item={ItemId} town={TownId} kingdom={KingdomId} other={OtherKingdomId} season={Season}";
        }
    }
}
